#!/usr/bin/env node
// Every glossary entry still has its term, and the glossary's index matches its files.
//
// The glossary is one file per domain under `docs/product/glossary/`, each opening `# <Domain>`
// and holding entries that each start `- **Term** —`. It was one 40,626-word file, the most
// edited in the repository (38 commits in three days), and every branch that added a term
// conflicted with every other. `docs/product/glossary.md` is now the index: generated by
// `node scripts/check-glossary.mjs --write`, one `## <Domain>` heading per file (so links to
// `glossary.md#operations` still land) and its terms sorted, one per line, so two branches adding
// different terms usually touch different lines. The check fails while the index is stale; on a
// conflict in it, take either side and run `--write` again.
//
// On 2026-08-04 the Close-out entry was written by replacing the line that read
// `- **Blocked / Ready** — the shop's one readiness vocabulary, and the only two states a booking's`
// (commit 2bedae366). The rest of that definition stayed exactly where it was, one indent
// deeper, so the readiness vocabulary — the `readinessStatusText`/`readinessStatusTone` rule
// and the offline-manifest exception `src/components/OfflineManifestView.tsx` cites by name —
// spent five weeks living inside the definition of the end-of-day ritual, opening mid-sentence
// on "readiness check has." with no antecedent. `pnpm check:docs` reads links, and a
// decapitated entry has no broken link in it, so nothing said a word.
//
// The tell is mechanical: wrapped prose never starts a line with a lowercase word right after
// a finished sentence, because English sentences start capitalized. When it does, a line above
// it was taken away. Abbreviations are the one honest way to end a line in a period without
// ending a sentence, so they are exempt.
//
// The index opens with the settled words: `config/vocabulary.mjs` rendered as a table, the
// concept, its screen word in each locale, the words refused in its place and what holds the
// refusal (`scripts/check-vocabulary.mjs` for most rows). A row that names a glossary `term` must
// name one that exists, so the table and the entries cannot drift apart.

import { readdir, readFile, writeFile } from "node:fs/promises";
import path from "node:path";
import process from "node:process";
import { fileURLToPath } from "node:url";

import { VOCABULARY } from "../config/vocabulary.mjs";

const ROOT = path.join(import.meta.dirname, "..");
export const GLOSSARY_DIR = "docs/product/glossary";
export const GLOSSARY_INDEX = "docs/product/glossary.md";

// The abbreviations this document actually ends a wrapped line with. A period here closes a
// word, not a sentence, so a lowercase word on the next line is ordinary prose.
const ABBREVIATIONS = /(?:\b[a-z]\.|\b(?:e\.g|i\.e|etc|vs|a\.m|p\.m|No|Inc|St|approx)\.)$/i;

/**
 * A continuation line of a bullet — indented, not itself a bullet — that opens a lowercase
 * word immediately after a completed sentence. That is a definition whose term was deleted.
 */
export function findDecapitatedEntries(contents) {
  const lines = contents.split("\n");
  const found = [];
  let inFence = false;

  for (let index = 1; index < lines.length; index += 1) {
    const line = lines[index];
    if (line.trimStart().startsWith("```")) {
      inFence = !inFence;
      continue;
    }
    if (inFence) continue;
    if (!/^ {2,}\S/.test(line)) continue;
    if (/^ *[-*] /.test(line)) continue;
    if (!/^\s*[a-z`]/.test(line)) continue;

    const previous = lines[index - 1].trimEnd();
    if (!/[.!?]$/.test(previous)) continue;
    if (ABBREVIATIONS.test(previous)) continue;

    found.push({ line: index + 1, text: line.trim() });
  }

  return found;
}

/** A domain file's title (its `# ` line) and its terms, in file order. */
export function readDomain(file, contents) {
  return {
    file,
    title: contents.match(/^# (.+)$/m)?.[1]?.trim() ?? null,
    terms: [...contents.matchAll(/^- \*\*([^*]+)\*\*/gm)].map((match) => match[1].trim()),
  };
}

/** The settled-words table, one row per `config/vocabulary.mjs` concept, in its order. */
export function vocabularyTable(vocabulary = VOCABULARY) {
  const cell = (text) => text.replaceAll("|", "\\|");
  return [
    "## Settled words",
    "",
    "Generated from `config/vocabulary.mjs`, which `scripts/check-vocabulary.mjs` reads: a refused",
    "word in a message bundle fails `pnpm check:repo`. The Spanish reasoning is",
    "[src/i18n/locales/es-ES/README.md](../../src/i18n/locales/es-ES/README.md).",
    "",
    "| Concept | en-US | es-ES | Refused | Held by |",
    "| --- | --- | --- | --- | --- |",
    ...vocabulary.map((row) => {
      const refused =
        row.refuse.map((rule) => `${rule.word} (${rule.locale})`).join("; ") || "see held by";
      return `| ${cell(row.term ?? row.id)} | ${cell(row.en)} | ${cell(row.es)} | ${cell(refused)} | ${cell(row.heldBy ?? "check-vocabulary")} |`;
    }),
  ];
}

/** Every vocabulary row whose `term` is not a glossary entry. */
export function missingVocabularyTerms(domains, vocabulary = VOCABULARY) {
  const terms = new Set(domains.flatMap((domain) => domain.terms));
  return vocabulary
    .filter((row) => row.term && !terms.has(row.term))
    .map(
      (row) =>
        `config/vocabulary.mjs: row "${row.id}" names the glossary term "${row.term}", which no domain file defines`,
    );
}

/**
 * The index: a fixed preamble, the settled-words table, then one `## <Domain>` section per file,
 * files sorted by name.
 */
export function glossaryIndex(domains, vocabulary = VOCABULARY) {
  const lines = [
    "# Dive-domain glossary",
    "",
    "Domain terms agents must use correctly — in code, UI copy, and data models. When you introduce a",
    "new domain concept, define it in the same PR, in the domain file it belongs to under",
    "[glossary/](glossary/): one entry per term, starting `- **Term** —`.",
    "",
    "This page is generated by `node scripts/check-glossary.mjs --write` and `pnpm check:glossary`",
    "fails while it is stale. Grep the domain files for a term; this index says which file holds it.",
    "",
    ...vocabularyTable(vocabulary),
  ];
  for (const domain of [...domains].sort((a, b) => a.file.localeCompare(b.file))) {
    lines.push(
      "",
      `## ${domain.title}`,
      "",
      `[glossary/${domain.file}](glossary/${domain.file})`,
      "",
    );
    for (const term of [...domain.terms].sort((a, b) => a.localeCompare(b, "en"))) {
      lines.push(`- ${term}`);
    }
  }
  return `${lines.join("\n")}\n`;
}

/** Every domain file with its contents, sorted by name. */
async function readDomains(root) {
  const files = (await readdir(path.join(root, GLOSSARY_DIR)))
    .filter((name) => name.endsWith(".md"))
    .sort();
  return Promise.all(
    files.map(async (file) => ({
      file,
      contents: await readFile(path.join(root, GLOSSARY_DIR, file), "utf8"),
    })),
  );
}

if (process.argv[1] && path.resolve(process.argv[1]) === fileURLToPath(import.meta.url)) {
  const domains = await readDomains(ROOT);
  const problems = [];
  for (const { file, contents } of domains) {
    for (const item of findDecapitatedEntries(contents)) {
      problems.push(`${GLOSSARY_DIR}/${file}:${item.line}: ${item.text.slice(0, 140)}`);
    }
  }
  if (problems.length > 0) {
    console.error(
      `Glossary entries that lost their term:\n${problems.map((p) => `- ${p}`).join("\n")}`,
    );
    console.error(
      "A definition continues mid-sentence under the entry above it, which means its `- **Term** —` line was overwritten. Restore the term; do not re-wrap the paragraph to hide the seam.",
    );
    process.exit(1);
  }

  const parsed = domains.map(({ file, contents }) => readDomain(file, contents));
  const untitled = parsed.filter((domain) => !domain.title).map((domain) => domain.file);
  if (untitled.length > 0) {
    console.error(`Glossary domain files with no \`# <Domain>\` title: ${untitled.join(", ")}`);
    process.exit(1);
  }
  const missing = missingVocabularyTerms(parsed);
  if (missing.length > 0) {
    console.error(missing.join("\n"));
    process.exit(1);
  }
  const index = glossaryIndex(parsed);
  if (process.argv.includes("--write")) {
    await writeFile(path.join(ROOT, GLOSSARY_INDEX), index);
  } else {
    const current = await readFile(path.join(ROOT, GLOSSARY_INDEX), "utf8").catch(() => "");
    if (current !== index) {
      console.error(
        `${GLOSSARY_INDEX} is stale: run \`node scripts/check-glossary.mjs --write\` (on a merge conflict in it, take either side and run it again).`,
      );
      process.exit(1);
    }
  }

  const terms = parsed.reduce((sum, domain) => sum + domain.terms.length, 0);
  console.log(
    `glossary: ${terms} entries in ${parsed.length} domain files, every one under its own term, index current`,
  );
}
